const express = require('express');
const router = express.Router();
const { getHealthStatus } = require('../controllers/healthController');

router.get('/', getHealthStatus);

module.exports = router;

const getHealthStatus = (req, res) => {
  res.status(200).json({
    status: 'success',
    message: 'Server is healthy and operational',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
};

module.exports = {
  getHealthStatus
};

const errorHandler = (err, req, res, next) => {
  const statusCode = res.statusCode === 200 ? 500 : res.statusCode;
  res.status(statusCode).json({
    status: 'error',
    message: err.message,
    stack: process.env.NODE_ENV === 'production' ? null : err.stack
  });
};

module.exports = errorHandler;

const mongoose = require('mongoose');
const envConfig = require('./envConfig');

const connectDB = async () => {
  try {
    const conn = await mongoose.connect(envConfig.MONGO_URI);
    console.log(`MongoDB Connected: ${conn.connection.host}`);
  } catch (error) {
    console.error(`Database Connection Error: ${error.message}`);
    process.exit(1);
  }
};

module.exports = connectDB;

const dotenv = require('dotenv');

dotenv.config();

module.exports = {
  PORT: process.env.PORT || 5000,
  NODE_ENV: process.env.NODE_ENV || 'development',
  MONGO_URI: process.env.MONGO_URI || 'mongodb://localhost:27017/express_app'
};

const express = require('express');
const path = require('path');

const app = express();

const PORT = process.env.PORT || 3000;

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// Endpoint 
app.get('/home', (req, res) => {
  res.send('Hello, this is the home page of the demo project');
});

// Home page endpoint
app.get('/home', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'home.html'), (err) => {
    if (err) res.send('Home Page');
  });
});

// Items page endpoint
app.get('/items', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'items.html'), (err) => {
    if (err) res.send('Items Page');
  });
});

// Contact Us endpoint
app.get('/contactus', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'contactus.html'), (err) => {
    if (err) res.send('Contact Us Page');
  });
});

// Root route
app.get('/', (req, res) => {
  res.redirect('/home');
});

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;




